import{_ as i,C as r,o,c as n,j as a,a as s,E as d,a6 as t}from"./chunks/framework.jAo0vQjE.js";const E=JSON.parse(`{"title":"I Still Prefer MCP Over Skills","description":"David Mohl's opinion piece: skills are good as knowledge (how to use a tool you already have, your jargon, a file format), but connecting an agent to a service should go through an MCP server the service owns, not a CLI plus a SKILL.md; the best setup is a skill that documents an MCP server.","frontmatter":{"schema_version":1,"id":"paper-mohl-mcp-over-skills","type":"paper","slug":"mohl-mcp-over-skills","title":"I Still Prefer MCP Over Skills","summary":"David Mohl's opinion piece: skills are good as knowledge (how to use a tool you already have, your jargon, a file format), but connecting an agent to a service should go through an MCP server the service owns, not a CLI plus a SKILL.md; the best setup is a skill that documents an MCP server.","topics":["mcp","coding-agents"],"status":"reviewed","review":{"reviewed_on":"2026-11-08T00:00:00.000Z","notes":"Publication approved by the owner on 2026-11-08 (\\"approve\\" for all seven 2026-11-08 import drafts; the empty Personal insights section was deleted at the owner's choice). The text is AI-assisted; see authorship."},"visibility":"public","publication":"published","created":"2026-11-08T00:00:00.000Z","updated":"2026-11-08T00:00:00.000Z","authorship":{"author":"owner","ai_involvement":"assisted"},"rights":"own","authors":["David Mohl"],"year":2026,"venue":"david.coffee (personal blog)","url":"https://david.coffee/i-still-prefer-mcp-over-skills/","concepts":["concept-model-context-protocol","concept-agent-skills"],"prerequisites":["concept-model-context-protocol","concept-agent-skills"],"related":["lecture-stanford-cs146s-07","concept-customization-mechanisms","paper-cloudflare-enterprise-mcp"],"sources":[{"key":"mohl2026","title":"I Still Prefer MCP Over Skills","kind":"web","authors":["David Mohl"],"year":2026,"url":"https://david.coffee/i-still-prefer-mcp-over-skills/","accessed":"2026-11-08T00:00:00.000Z","note":"Personal blog, 2026-04-02; CS146S Week 4 reading. An opinion piece. Locators are the post's section headings."},{"key":"cs146s-1013","title":"Customizing your agentic setup (CLAUDE.md, AGENTS.md, hooks) (CS146S, Fall 2026, lecture of 2026-10-13)","kind":"lecture","authors":["Mihail Eric"],"year":2026,"url":"https://docs.google.com/presentation/d/152VaUifBKH4T6hxd6fCKKM9kJTSAuBmkF8zSYwuTYAo/edit","accessed":"2026-11-08T00:00:00.000Z","note":"Official slides (text export): 'APIs vs MCP vs Skills' and 'Additional MCP Perks'."}]},"headers":[],"relativePath":"papers/mohl-mcp-over-skills.md","filePath":"papers/mohl-mcp-over-skills.md"}`),h={name:"papers/mohl-mcp-over-skills.md"};function c(p,e,u,k,g,m){const l=r("AtlasPageHeader");return o(),n("div",null,[e[0]||(e[0]=a("h1",{id:"i-still-prefer-mcp-over-skills-david-mohl",tabindex:"-1"},[s("I Still Prefer MCP Over Skills (David Mohl) "),a("a",{class:"header-anchor",href:"#i-still-prefer-mcp-over-skills-david-mohl","aria-label":'Permalink to "I Still Prefer MCP Over Skills (David Mohl)"'},"​")],-1)),d(l),e[1]||(e[1]=t('<h2 id="in-one-paragraph" tabindex="-1">In one paragraph <a class="header-anchor" href="#in-one-paragraph" aria-label="Permalink to &quot;In one paragraph&quot;">​</a></h2><p dir="rtl" lang="ar-EG">المقالة رد على موجة &quot;MCP is dead, skills are the new standard&quot;. موقف الكاتب: الـ skills ممتازة كـ <strong>معرفة</strong> (إزاي تستخدم أداة موجودة، المصطلحات الداخلية، التعامل مع نوع ملفات)، بس لما الـ skill تبدأ بـ &quot;install this CLI first&quot; عشان توصل لخدمة، تبقى ضفت طبقة مالهاش لازمة. التوصيل بالخدمات مكانه MCP server الخدمة نفسها بتملكه. وأحسن حاجة الاتنين مع بعض: skill بتشرح الـ MCP server.</p><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><ul dir="rtl" lang="ar-EG"><li dir="rtl" lang="ar-EG">تفرّق بين skill &quot;pure&quot; (معرفة) وskill بتعتمد على CLI عشان تعمل حاجة.</li><li dir="rtl" lang="ar-EG">تعدّ حجج الكاتب لـ MCP وتعرف حدود كل حجة.</li><li dir="rtl" lang="ar-EG">تصمم &quot;manual for a connector&quot;: skill فوق MCP server.</li></ul><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p dir="rtl" lang="ar-EG">الكاتب &quot;very heavy AI user&quot; وبيقول إن الـ narrative بقى إن كل integration محتاجة CLI مخصوصة وmarkdown manual. وده بيفشل في بيئات كتير: ChatGPT وPerplexity وClaude على الـ web مابيشغّلوش CLIs، فأي skill معتمدة على CLI &quot;dead on arrival&quot; هناك <span class="atlas-citation">[<a href="#source-mohl2026">mohl2026</a>, The Friction with Skills]</span>.</p><h2 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Method&quot;">​</a></h2><h3 id="what-he-likes-about-mcp" tabindex="-1">What he likes about MCP <a class="header-anchor" href="#what-he-likes-about-mcp" aria-label="Permalink to &quot;What he likes about MCP&quot;">​</a></h3><p dir="rtl" lang="ar-EG">الـ MCP &quot;API abstraction&quot;: الموديل يعرف <strong>إيه</strong> مش <strong>إزاي</strong>؛ ينادي <code>devonthink.do_x()</code> والـ server يتصرف <span class="atlas-citation">[<a href="#source-mohl2026">mohl2026</a>, What I Love About MCP]</span>. ومميزاته عنده:</p><table tabindex="0"><thead><tr><th>His point</th><th>What it means</th><th>The catch (my reading)</th></tr></thead><tbody><tr><td>Zero-install remote usage</td><td dir="rtl" lang="ar-EG">تدّي الـ client الـ URL وخلاص</td><td dir="rtl" lang="ar-EG">للـ remote servers بس</td></tr><tr><td>Seamless updates</td><td dir="rtl" lang="ar-EG">الـ server يتحدّث، والكل ياخد الجديد</td><td dir="rtl" lang="ar-EG">التحديث ممكن يكسر schemas بتعتمد عليها</td></tr><tr><td>Saner auth</td><td dir="rtl" lang="ar-EG">OAuth بدل tokens في ملفات</td><td dir="rtl" lang="ar-EG">OAuth لوحده مش أمان: scopes وتخزين وrotation</td></tr><tr><td>True portability</td><td dir="rtl" lang="ar-EG">نفس الـ server من الموبايل والـ web والـ Mac</td><td dir="rtl" lang="ar-EG">مش كل client بيدعم كل الـ features</td></tr><tr><td>Sandboxing</td><td dir="rtl" lang="ar-EG">interface محدود بدل shell كامل</td><td dir="rtl" lang="ar-EG">&quot;محدود&quot; مش &quot;آمن&quot; من غير authorization صح</td></tr><tr><td>Smart discovery</td><td dir="rtl" lang="ar-EG">tool search بيحمّل الأدوات وقت الحاجة</td><td dir="rtl" lang="ar-EG">ده بيعتمد على الـ client</td></tr></tbody></table><p dir="rtl" lang="ar-EG">ونفس القايمة تقريبًا موجودة في slides المحاضرة كـ &quot;Additional MCP Perks&quot;: seamless auth، وسهولة الـ versioning، والـ portability، والـ sandboxing للـ remote MCP <span class="atlas-citation">[<a href="#source-cs146s-1013">cs146s-1013</a>, Additional MCP Perks]</span>.</p><h3 id="the-friction-with-cli-backed-skills" tabindex="-1">The friction with CLI-backed skills <a class="header-anchor" href="#the-friction-with-cli-backed-skills" aria-label="Permalink to &quot;The friction with CLI-backed skills&quot;">​</a></h3><p><span class="atlas-citation">[<a href="#source-mohl2026">mohl2026</a>, The Friction with Skills]</span>:</p><ul dir="rtl" lang="ar-EG"><li dir="rtl" lang="ar-EG"><strong>Deployment:</strong> الـ CLIs لازم تتنشر وتتثبّت (binaries، npm، uv).</li><li dir="rtl" lang="ar-EG"><strong>Secrets:</strong> الـ tokens بتتحط فين؟ <code>.env</code> plain text، أو بيئة ephemeral بتنسى الـ secrets بكرة.</li><li dir="rtl" lang="ar-EG"><strong>Fragmentation:</strong> كل أداة بتثبّت الـ skills بطريقة؛ skill من منصة ممكن تفشل في التانية بـ YAML errors.</li><li dir="rtl" lang="ar-EG"><strong>Context bloat:</strong> ممكن تحمّل <code>SKILL.md</code> كامل عشان تنادي حاجة زي <code>car.turn_on()</code>.</li></ul><h3 id="connectors-vs-manuals" tabindex="-1">Connectors vs manuals <a class="header-anchor" href="#connectors-vs-manuals" aria-label="Permalink to &quot;Connectors vs manuals&quot;">​</a></h3><p dir="rtl" lang="ar-EG">قاعدته <span class="atlas-citation">[<a href="#source-mohl2026">mohl2026</a>, Connectors vs. Manuals]</span>:</p><ul dir="rtl" lang="ar-EG"><li dir="rtl" lang="ar-EG"><strong>MCP</strong> = الـ interface للاتصال بحاجة برّه، والخدمة نفسها تملكه. أمثلته: Google Calendar (عندها remote MCP بـ OAuth)، وNotion (<code>mcp.notion.so/mcp</code>)، وأدوات زي Hopper وXcode بـ MCP جوه الـ session الحية فبيعرفوا context مستحيل CLI يعرفه.</li><li dir="rtl" lang="ar-EG"><strong>Skills</strong> تبقى &quot;pure&quot;: تعليم أدوات موجودة (<code>curl</code>، <code>git</code>، <code>gh</code>، <code>gcloud</code>)، وworkflows والمصطلحات الداخلية، والتعامل مع formats (زي الـ PDF skill)، وأنماط الـ secrets (&quot;use fnox in this repo&quot;). بس حتى هنا: لإدارة issues، GitHub MCP أحسن من skill على <code>gh</code>.</li></ul><p dir="rtl" lang="ar-EG">ويقترح أسامي: الـ skills تتسمى <code>LLM_MANUAL.md</code> والـ MCPs تتسمى Connectors.</p><h3 id="skills-mcp-a-manual-for-a-connector" tabindex="-1">Skills + MCP: a manual for a connector <a class="header-anchor" href="#skills-mcp-a-manual-for-a-connector" aria-label="Permalink to &quot;Skills + MCP: a manual for a connector&quot;">​</a></h3><p dir="rtl" lang="ar-EG">أقوى جزء <span class="atlas-citation">[<a href="#source-mohl2026">mohl2026</a>, Skills + MCP]</span>: لما يشتغل مع MCP server ويكتشف gotchas (format تاريخ <code>YYYY-MM-DD</code> مش <code>YYYYMMDD</code>، search بيقص النتايج إلا لو زوّدت parameter، أداة اسمها مضلل)، بيطلب من Claude يلم كل اللي اتعلموه في skill. الـ MCP بيعمل الاتصال، والـ skill &quot;cheat sheet&quot; عشان مايعيدش نفس الأخطاء كل session.</p><h2 id="diagram" tabindex="-1">Diagram <a class="header-anchor" href="#diagram" aria-label="Permalink to &quot;Diagram&quot;">​</a></h2><p dir="rtl" lang="ar-EG">مفيش رسمة خاصة بالصفحة؛ رسمة <a href="./../concepts/customization-mechanisms">Choosing Where an Instruction Lives</a> فيها نفس الفكرة: خدمة برّه = MCP server ومعاه skill للـ workflow.</p><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><p dir="rtl" lang="ar-EG">مقال رأي: مفيش قياسات. الأمثلة تجارب الكاتب الشخصية.</p><h2 id="technical-example" tabindex="-1">Technical example <a class="header-anchor" href="#technical-example" aria-label="Permalink to &quot;Technical example&quot;">​</a></h2><p dir="rtl" lang="ar-EG">skill من النوع اللي بيوصفه (مثال من عندي؛ اسم الـ server والأدوات افتراضيين):</p><div class="language-markdown vp-adaptive-theme"><button title="Copy code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: notes-mcp-guide</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: How to use the notes MCP server correctly. Use before calling any notes.* tool.</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Notes MCP: known gotchas</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Dates must be </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`YYYY-MM-DD`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`YYYYMMDD`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> returns an empty list, not an error.</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> `notes.search`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> returns 20 results by default; pass </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`limit`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> for more.</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> To link notes, call </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`notes.get`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> first: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`notes.link`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> needs the note id, not the title.</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Never call </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`notes.delete`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> without showing the user the note title first.</span></span></code></pre></div><p dir="rtl" lang="ar-EG">الـ skill دي مابتعملش أي اتصال؛ كل الأفعال لسه أدوات MCP. هي بس بتوفّر الأخطاء اللي اتصلحت قبل كده.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul dir="rtl" lang="ar-EG"><li dir="rtl" lang="ar-EG">Stated by the author: موقفه مبني على استخدامه الشخصي، وبيقول بوضوح إن الاتنين ليهم مكان <span class="atlas-citation">[<a href="#source-mohl2026">mohl2026</a>, Connectors vs. Manuals]</span>. وفي الآخر بيعلن عن منتجين بتوعه (MCP Nest وWarplet)، فخد ده في الاعتبار.</li><li dir="rtl" lang="ar-EG">My assessment: الحجج قوية لـ remote services، أضعف لأدوات محلية موجودة أصلًا: لو عندك CLI موثوقة ومثبّتة، MCP server جديد ممكن يزوّد تعقيد من غير مكسب. والـ remote MCP بيحط ثقة في الـ server owner، وده موضوع security لوحده (شوف <a href="./cloudflare-enterprise-mcp">Cloudflare&#39;s enterprise MCP architecture</a>).</li></ul><h2 id="exercises" tabindex="-1">Exercises <a class="header-anchor" href="#exercises" aria-label="Permalink to &quot;Exercises&quot;">​</a></h2>',31)),e[2]||(e[2]=a("div",{class:"atlas-callout atlas-callout--exercise",role:"note"},[a("p",{class:"atlas-callout-title"},"Exercise: Connector or manual"),a("p",{dir:"rtl",lang:"ar-EG"},[s("لكل حالة: MCP، ولا skill، ولا الاتنين؟ (1) الـ agent يعمل events في Google Calendar. (2) الـ agent يكتب commit messages على convention الفريق. (3) الـ agent يدير issues في Jira بـ workflow الـ triage بتاع الفريق. (4) الـ agent يستخدم "),a("code",null,"ffmpeg"),s(" المثبّت عندك.")]),a("details",{class:"details custom-block"},[a("summary",null,"Solution"),a("p",{dir:"rtl",lang:"ar-EG"},[s('(1) MCP (الخدمة بتوفّر remote MCP بـ OAuth). (2) skill pure. (3) الاتنين: MCP للقدرة وskill للـ triage workflow. (4) skill بتعلّم أداة موجودة؛ مفيش داعي لـ "ffmpeg MCP" '),a("span",{class:"atlas-citation"},[s("["),a("a",{href:"#source-mohl2026"},"mohl2026"),s(", Connectors vs. Manuals]")]),s(".")])])],-1)),e[3]||(e[3]=a("div",{class:"atlas-callout atlas-callout--exercise",role:"note"},[a("p",{class:"atlas-callout-title"},"Exercise: Steelman the other side"),a("p",{dir:"rtl",lang:"ar-EG"},"اكتب حجتين لصالح CLI + skill بدل MCP server."),a("details",{class:"details custom-block"},[a("summary",null,"Solution"),a("p",{dir:"rtl",lang:"ar-EG"},"مثلًا: (1) الـ CLI موجودة أصلًا ومتجرّبة ومستخدمة من البشر كمان، فمفيش كود جديد تصونه. (2) الـ CLI بتشتغل offline ومن غير ما تدّي طرف تالت صلاحيات على حسابك. دي مش حجج المقالة؛ هي الطرف التاني للنقاش.")])],-1)),e[4]||(e[4]=t('<h2 id="review-questions" tabindex="-1">Review questions <a class="header-anchor" href="#review-questions" aria-label="Permalink to &quot;Review questions&quot;">​</a></h2><ol dir="rtl" lang="ar-EG"><li dir="rtl" lang="ar-EG">إيه الفرق بين &quot;pure&quot; skill وskill بتعتمد على CLI عند الكاتب؟</li><li dir="rtl" lang="ar-EG">ليه Xcode MCP بيعرف حاجات مستحيل <code>xcode-cli</code> يعرفها؟</li><li dir="rtl" lang="ar-EG">إيه فكرة &quot;manual for a connector&quot;، وإمتى تكتب skill زي دي؟</li><li dir="rtl" lang="ar-EG">أنهي ميزة من مميزات MCP عنده موجودة كمان في slides المحاضرة؟</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p dir="rtl" lang="ar-EG">المقال نفسه <span class="atlas-citation">[<a href="#source-mohl2026">mohl2026</a>]</span>، وslides محاضرة CS146S عن APIs وMCP والـ skills <span class="atlas-citation">[<a href="#source-cs146s-1013">cs146s-1013</a>]</span>. والشرح مبني كمان على study notes عن CS146S Week 4 (2026-11-08)؛ الـ notes بتقول إن الكاتب &quot;مش ضد الـ Skills خالص&quot;، بس هو كاتب &quot;I just don&#39;t like Skills&quot; وبيقبل الـ pure skills بس.</p>',4))])}const f=i(h,[["render",c]]);export{E as __pageData,f as default};
